"""For every mutation accepted by both validators, verify lookups match the derived FIB."""
import json, random, sys
sys.path.insert(0, '/workspace/tmp/dev')
from harness import run, hx
import ref, imgtool

base = json.load(open('/workspace/tmp/dev/med_img.json'))
rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 11)

def mutate(base):
    m = json.loads(json.dumps(base))
    rows = imgtool.rows_to_int(m)
    sizes = [(s, r) for s in range(11) for r in range(len(rows[s]))]
    kind = rng.randrange(10)
    if kind <= 5 and sizes:
        s, r = rng.choice(sizes)
        for _ in range(rng.randint(1, 3)):
            rows[s][r] ^= 1 << rng.randrange(256)
    elif kind == 6:
        s = rng.randrange(11)
        m['cells'][s] = max(0, m['cells'][s] + rng.choice([-2, -1, 1, 2]))
    elif kind == 7 and m['bitmaps']:
        i = rng.randrange(len(m['bitmaps']))
        m['bitmaps'][i] = '%016x' % (int(m['bitmaps'][i], 16) ^ (1 << rng.randrange(64)))
    elif kind == 8 and m['nexthops']:
        i = rng.randrange(len(m['nexthops']))
        m['nexthops'][i] = rng.randrange(0, 4194304)
    else:
        for lst in (m['front16'], m['front64']):
            if lst and rng.random() < 0.5:
                e = lst[rng.randrange(len(lst))]
                if rng.random() < 0.5: e[1] = rng.randrange(11)
                else: e[2] = max(0, e[2] + rng.choice([-1, 1]))
        if m['root'] and rng.random() < 0.5:
            m['root'][1] = max(0, m['root'][1] + rng.choice([-1, 1]))
    imgtool.ints_to_rows(m, rows)
    return m

cands = []
for i in range(int(sys.argv[2]) if len(sys.argv) > 2 else 300):
    m = mutate(base)
    ok, reason, fib = ref.validate_image(m, want_fib=True)
    if ok: cands.append((i, m, fib))
print('accepted', len(cands))
bad = 0
for (i, m, fib) in cands:
    addrs = [a for (a, l, h) in fib][:25] + [rng.getrandbits(128) for _ in range(15)]
    if not addrs: addrs = [0, (1 << 128) - 1]
    Q = ref.make_lpm(fib)
    want = [Q(a) for a in addrs]
    resp = run({'cases': [{'ops': [['load', m], ['image_query', [hx(a) for a in addrs]]]}]})
    r = resp['results'][0]
    if r['loads'] != [True] or r['answers'] != want:
        bad += 1
        print('  LOOKUP MISMATCH #%d load=%s' % (i, r['loads']))
        for a, w, g in zip(addrs, want, r['answers']):
            if w != g: print('    addr %s want %s got %s' % (hx(a), w, g))
        if bad > 3: break
print('lookup mismatches', bad, 'of', len(cands))
